// Parse + normalização do payload whatsmeow da Avisa API para o envelope
// Meta Cloud API que o Whatsapp::IncomingMessageAvisaService parseia.
//
// Payload real observado (abril/2026):
//   body.jsonData = JSON stringificado com { event: { Info, Message }, type: 'Message' }
//   body.token    = token por instância (para verificar origem)
//
// event.Info relevante:
//   - SenderAlt: '<phone>@s.whatsapp.net' (ex: '5511999999999@s.whatsapp.net')
//   - Sender:    pode vir '@lid' (linked-id ofuscado) — preferir SenderAlt
//   - PushName:  nome exibido do contato
//   - IsFromMe:  true significa mensagem enviada pela própria empresa (pular)
//   - IsGroup:   true significa grupo (pular por ora)
//   - ID:        id único da mensagem
//   - Timestamp: ISO8601
//   - Type:      'text' | ... (usamos para fallback; preferimos detectar por event.Message keys)
//
// event.Message shapes whatsmeow:
//   extendedTextMessage | conversation            -> text
//   imageMessage { URL, mimetype, caption }       -> image
//   audioMessage { URL, mimetype }                -> audio
//   videoMessage { URL, mimetype, caption }       -> video
//   documentMessage { URL, mimetype, caption, fileName } -> document
//   stickerMessage { URL, mimetype }              -> sticker
//   locationMessage { degreesLatitude, degreesLongitude } -> location
//
// AJUSTE_AQUI: se a Avisa começar a ofuscar a URL da mídia (mmg.whatsapp.net
// só funciona com mediaKey), vai ser necessário decriptar com whatsmeow
// antes de repassar ao Chatwoot. Implementar depois do 1º teste real.

const results = [];
for (const item of $input.all()) {
  const rawBody = item.json.body || item.json;

  // Verifica token da instância Avisa (fornecido por nós no painel).
  const expectedInstanceToken = $env.SYNAPSEOS_AVISA_INSTANCE_TOKEN;
  if (expectedInstanceToken && rawBody.token !== expectedInstanceToken) {
    throw new Error('Invalid Avisa instance token');
  }

  let parsed;
  try {
    parsed = typeof rawBody.jsonData === 'string' ? JSON.parse(rawBody.jsonData) : rawBody.jsonData;
  } catch (e) {
    throw new Error('Failed to parse jsonData: ' + e.message);
  }
  if (!parsed || parsed.type !== 'Message') continue;

  const info = parsed.event?.Info || {};
  const msg = parsed.event?.Message || {};

  // Skip: mensagens da própria empresa (echo) e grupos.
  if (info.IsFromMe) continue;
  if (info.IsGroup) continue;

  // Extrai número do contato. SenderAlt é o JID real; Sender pode ser @lid ofuscado.
  const sender = info.SenderAlt || info.Sender || '';
  const fromJid = sender.split('@')[0].replace(/[^0-9]/g, '');
  if (!fromJid) continue;

  // Número da empresa (Synapse OS / inbox). A Avisa não entrega esse campo
  // nativamente; definimos via env por flow (uma flow por inbox/instância).
  const businessPhone = $env.SYNAPSEOS_AVISA_BUSINESS_PHONE;
  if (!businessPhone) {
    throw new Error('SYNAPSEOS_AVISA_BUSINESS_PHONE env var não configurada para esta flow');
  }

  const pushName = info.PushName || '';
  const msgId = info.ID || String(Date.now());
  const ts = info.Timestamp ? Math.floor(new Date(info.Timestamp).getTime() / 1000) : Math.floor(Date.now() / 1000);

  // Detecta tipo pelas chaves de Message (prioridade sobre Info.Type).
  let metaType = 'text';
  let metaPayload = null;
  if (msg.extendedTextMessage?.text) {
    metaType = 'text';
    metaPayload = { text: { body: msg.extendedTextMessage.text } };
  } else if (msg.conversation) {
    metaType = 'text';
    metaPayload = { text: { body: msg.conversation } };
  } else if (msg.imageMessage) {
    metaType = 'image';
    metaPayload = { image: {
      url: msg.imageMessage.URL,
      mime_type: msg.imageMessage.mimetype || 'image/jpeg',
      caption: msg.imageMessage.caption || ''
    }};
  } else if (msg.audioMessage) {
    metaType = 'audio';
    metaPayload = { audio: {
      url: msg.audioMessage.URL,
      mime_type: msg.audioMessage.mimetype || 'audio/ogg'
    }};
  } else if (msg.videoMessage) {
    metaType = 'video';
    metaPayload = { video: {
      url: msg.videoMessage.URL,
      mime_type: msg.videoMessage.mimetype || 'video/mp4',
      caption: msg.videoMessage.caption || ''
    }};
  } else if (msg.documentMessage) {
    metaType = 'document';
    metaPayload = { document: {
      url: msg.documentMessage.URL,
      mime_type: msg.documentMessage.mimetype || 'application/pdf',
      filename: msg.documentMessage.fileName || 'document',
      caption: msg.documentMessage.caption || ''
    }};
  } else if (msg.stickerMessage) {
    metaType = 'sticker';
    metaPayload = { sticker: {
      url: msg.stickerMessage.URL,
      mime_type: msg.stickerMessage.mimetype || 'image/webp'
    }};
  } else if (msg.locationMessage) {
    metaType = 'location';
    metaPayload = { location: {
      latitude: msg.locationMessage.degreesLatitude,
      longitude: msg.locationMessage.degreesLongitude,
      name: msg.locationMessage.name || '',
      address: msg.locationMessage.address || ''
    }};
  } else {
    // Tipo não mapeado: vira texto de sistema com json inline.
    metaType = 'text';
    metaPayload = { text: { body: '[unsupported message type: ' + (info.Type || 'unknown') + ']' } };
  }

  const messageObj = Object.assign({
    from: fromJid,
    id: msgId,
    timestamp: String(ts),
    type: metaType
  }, metaPayload);

  results.push({
    json: {
      _phone_number: businessPhone,
      body: {
        object: 'whatsapp_business_account',
        entry: [{
          id: 'avisa',
          changes: [{
            field: 'messages',
            value: {
              messaging_product: 'whatsapp',
              metadata: {
                display_phone_number: businessPhone,
                phone_number_id: businessPhone
              },
              contacts: [{ wa_id: fromJid, profile: { name: pushName } }],
              messages: [messageObj]
            }
          }]
        }]
      }
    }
  });
}
return results;
